class Solution {
public:
    int countHighestScoreNodes(vector<int>& parents) {
        int n = parents.size();
        vector<vector<int>> children(n);
        for (int i = 1; i < n; i++) {
            children[parents[i]].push_back(i);
        }

        vector<int> size(n, 1);

        vector<int> order;
        order.reserve(n);
        order.push_back(0);
        for (int i = 0; i < n; i++) {
            int u = order[i];
            for (int v : children[u]) {
                order.push_back(v);
            }
        }

        for (int i = n - 1; i >= 0; i--) {
            int u = order[i];
            for (int v : children[u]) {
                size[u] += size[v];
            }
        }

        long long maxScore = 0;
        int count = 0;

        for (int u = 0; u < n; u++) {
            long long score = 1;
            for (int v : children[u]) {
                score *= size[v];
            }
            int rest = n - size[u];
            if (rest > 0) score *= rest;

            if (score > maxScore) {
                maxScore = score;
                count = 1;
            } else if (score == maxScore) {
                count++;
            }
        }

        return count;
    }
};
